// Arma el email al cliente según la plantilla del envío registrado en Django.
// Devuelve [] cuando el evento no lleva email (ej. pasa a "en producción").
const d = $input.first().json.body ?? {};
const t = d.tenant ?? {};
const o = d.order ?? {};
const c = d.customer ?? {};
const delivery = d.delivery;
if (!delivery || !delivery.recipient) return [];

const esc = s => String(s ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money = n => '$' + Math.round(Number(n ?? 0)).toLocaleString('es-AR');
const primary = t.primary_color || '#3D1A0E';
const accent = t.accent_color || '#E8889A';
const bg = t.bg_color || '#FDF6EC';
const button = (href, label) => href ? `
  <tr><td align="center" style="padding:0 32px 28px;">
    <a href="${esc(href)}" style="background:${accent};color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:999px;font-weight:bold;font-size:15px;display:inline-block;">${label}</a>
  </td></tr>` : '';

let subject, title, intro, badge, cta = '';
switch (delivery.template) {
  case 'order_created':
    subject = `Recibimos tu pedido #${o.id}`;
    title = '¡Recibimos tu pedido! 🍰';
    badge = 'Esperando seña';
    intro = `Para confirmarlo necesitamos que abones la seña de <strong>${money(o.deposit_amount)}</strong>.`;
    cta = button(o.url, 'Pagar seña →');
    break;
  case 'payment_received':
    subject = `¡Seña confirmada! Pedido #${o.id}`;
    title = '¡Tu pedido está confirmado! 🎉';
    badge = '✓ Seña pagada';
    intro = `Recibimos tu seña de <strong>${money(o.deposit_amount)}</strong>. Ya estamos preparando tu pedido y te avisamos cuando esté listo.`;
    break;
  case 'order_ready':
    subject = `¡Tu pedido #${o.id} está listo!`;
    title = '¡Tu pedido está listo! 🎂';
    badge = '✓ Listo';
    intro = o.delivery_method === 'delivery'
      ? 'Tu pedido ya está listo y en breve sale para tu domicilio.'
      : 'Tu pedido ya está listo. ¡Podés pasar a retirarlo!';
    intro += ` Resto a pagar: <strong>${money(o.balance_amount)}</strong>.`;
    break;
  case 'order_cancelled':
    subject = `Pedido #${o.id} cancelado`;
    title = 'Tu pedido fue cancelado';
    badge = 'Cancelado';
    intro = 'Lamentamos informarte que tu pedido fue cancelado. Si tenés dudas, respondé este mail o escribinos.';
    break;
  case 'custom':
    // Mensaje libre escrito por el admin desde el panel
    subject = String(delivery.subject ?? '').trim() || `Novedades de tu pedido #${o.id}`;
    title = esc(subject);
    badge = esc(o.status_display);
    intro = String(delivery.message ?? '').split('\n').filter(l => l.trim()).map(esc).join('<br>');
    break;
  default:
    return [];
}

const row = (label, value, strong = false) => `
  <tr>
    <td style="padding:10px 0;border-bottom:1px solid #f0e5e1;color:#746a68;font-size:14px;">${label}</td>
    <td align="right" style="padding:10px 0;border-bottom:1px solid #f0e5e1;font-size:14px;${strong ? 'font-weight:bold;' : ''}">${value}</td>
  </tr>`;

const items = (o.items ?? []).map(i =>
  row(`${esc(i.quantity)}x ${esc(i.product_name)}${i.variant_name ? ' — ' + esc(i.variant_name) : ''}`, money(i.subtotal), true)
).join('');

const totals = [
  o.delivery_cost ? row('Envío', money(o.delivery_cost)) : '',
  o.discount_amount ? row(`Descuento${o.coupon_code ? ' (' + esc(o.coupon_code) + ')' : ''}`, '-' + money(o.discount_amount)) : '',
  row('<strong>Total</strong>', money(o.total), true),
  row(`Seña (${Math.round(o.deposit_percentage ?? 0)}%)`, money(o.deposit_amount)),
  row('Resto a pagar', money(o.balance_amount)),
].join('');

const contact = [t.whatsapp && `WhatsApp ${esc(t.whatsapp)}`, t.instagram && `Instagram ${esc(t.instagram)}`, t.email && esc(t.email)]
  .filter(Boolean).join(' · ');

const notes = String(o.notes ?? '').trim();

const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
<body style="margin:0;padding:0;background:${bg};font-family:Arial,Helvetica,sans-serif;color:#342a29;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${bg};">
<tr><td align="center" style="padding:32px 16px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #f4dfd8;border-radius:16px;">
  <tr><td align="center" style="padding:32px 28px;background:${primary};border-radius:16px 16px 0 0;">
    ${t.logo_url ? `<img src="${esc(t.logo_url)}" alt="${esc(t.name)}" height="56" style="display:block;margin:0 auto 12px;">` : ''}
    <p style="margin:0 0 8px;color:#ffffff;opacity:.85;font-size:13px;font-weight:bold;letter-spacing:3px;">${esc(String(t.name ?? '').toUpperCase())}</p>
    <h1 style="margin:0;color:#ffffff;font-size:26px;line-height:1.3;">${title}</h1>
  </td></tr>
  <tr><td style="padding:30px 32px 18px;">
    <p style="margin:0 0 12px;font-size:18px;">Hola, <strong>${esc(c.name)}</strong> 👋</p>
    <p style="margin:0;color:#655a58;font-size:15px;line-height:1.7;">${intro}</p>
  </td></tr>
  <tr><td style="padding:8px 32px 24px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${bg};border-radius:12px;">
      <tr>
        <td style="padding:18px;"><span style="color:#8b7370;font-size:12px;">NÚMERO DE PEDIDO</span><br>
          <strong style="color:${primary};font-size:24px;">#${esc(o.id)}</strong></td>
        <td align="right" style="padding:18px;color:${primary};font-size:14px;font-weight:bold;">${badge}</td>
      </tr>
      <tr><td colspan="2" style="padding:0 18px 18px;color:#655a58;font-size:14px;">
        📅 ${esc(o.delivery_method_display)} — <strong>${esc(o.required_date_display)}</strong></td></tr>
    </table>
  </td></tr>
  <tr><td style="padding:0 32px 26px;">
    <h2 style="margin:0 0 12px;color:${primary};font-size:18px;">Detalle del pedido</h2>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${items}${totals}</table>
  </td></tr>
  ${notes ? `<tr><td style="padding:0 32px 28px;">
    <h2 style="margin:0 0 10px;color:${primary};font-size:18px;">Comentarios de tu pedido</h2>
    <div style="padding:16px;background:${bg};border-left:4px solid ${accent};border-radius:5px;color:#584b49;font-size:14px;line-height:1.6;">${esc(notes)}</div>
  </td></tr>` : ''}
  ${cta}
  <tr><td style="padding:22px 32px;background:#fffaf8;border-top:1px solid #f4e8e3;border-radius:0 0 16px 16px;">
    <p style="margin:0 0 6px;color:${primary};font-weight:bold;">¡Gracias por elegir ${esc(t.name)}! 💗</p>
    <p style="margin:0;color:#827674;font-size:13px;line-height:1.5;">Conservá el número #${esc(o.id)} como referencia de tu pedido.${contact ? '<br>' + contact : ''}</p>
  </td></tr>
</table>
</td></tr></table>
</body></html>`;

return [{ json: {
  to: delivery.recipient,
  subject: `${subject} — ${t.name}`,
  html,
  delivery_id: delivery.id,
  callback_url: delivery.callback_url,
} }];

// Aviso al equipo del negocio para pedidos nuevos y señas pagadas.
const d = $input.first().json.body ?? {};
if (!['order_created', 'payment_received'].includes(d.event)) return [];
const t = d.tenant ?? {};
const o = d.order ?? {};
const c = d.customer ?? {};
const money = n => '$' + Math.round(Number(n ?? 0)).toLocaleString('es-AR');
const header = d.event === 'payment_received'
  ? '✅ Seña pagada — ¡pedido confirmado para preparar!'
  : '🆕 Nuevo pedido (esperando seña)';
const items = (o.items ?? []).map(i => `• ${i.quantity}x ${i.product_name}${i.variant_name ? ' — ' + i.variant_name : ''}`).join('\n');
const text = [
  `🍰 ${t.name}`,
  header,
  '',
  `🧾 Pedido: #${o.id}`,
  `👤 Cliente: ${c.name}${c.phone ? ' (' + c.phone + ')' : ''}`,
  `📅 ${o.delivery_method_display}: ${o.required_date_display}`,
  '',
  items,
  '',
  `💰 Total: ${money(o.total)} · Seña: ${money(o.deposit_amount)}`,
  `📝 Comentarios: ${String(o.notes ?? '').trim() || 'Sin comentarios'}`,
].join('\n');
return [{ json: { text } }];
